请对以下 case 进行三维加权评分。

=== case_id ===
Case-07-sports-event-008

=== 用户原始指令 (query.txt) ===
弄个控球率那种比例的卡片 点一下能进里面 从日历读赛程 已完成的要标出来

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "弄个控球率那种比例的卡片 点一下能进里面 从日历读赛程 已完成的要标出来",
  "size": "2x4",
  "eventCandidates": [
    {
      "call": "clickToIntent",
      "args": {
        "intentName": "ViewCalendarEvent",
        "params": {
          "entityId": "match-001"
        }
      }
    }
  ],
  "dataModelSchema": {
    "data": {
      "calendar": {
        "items": [
          {
            "entityId": {
              "type": "string",
              "description": "日历赛事的唯一标识，用于点击进入赛事日程详情。",
              "sampleValue": "match-001"
            },
            "title": {
              "type": "string",
              "description": "日历赛事标题。",
              "sampleValue": "城东 vs 海湾"
            },
            "dtStart": {
              "type": "string",
              "description": "赛事开始时间，当天赛事使用 HH:MM 展示。",
              "sampleValue": "18:30"
            },
            "dtEnd": {
              "type": "string",
              "description": "赛事结束时间，当天赛事使用 HH:MM 展示。",
              "sampleValue": "20:10"
            },
            "eventLocation": {
              "type": "string",
              "description": "赛事地点或场馆。",
              "sampleValue": "主场"
            },
            "description": {
              "type": "string",
              "description": "赛事状态或补充说明，可用于标记已完成赛程。",
              "sampleValue": "已完成"
            }
          },
          {
            "entityId": {
              "type": "string",
              "description": "下一条日历赛事的唯一标识。",
              "sampleValue": "match-002"
            },
            "title": {
              "type": "string",
              "description": "下一条日历赛事标题。",
              "sampleValue": "北区杯小组赛"
            },
            "dtStart": {
              "type": "string",
              "description": "下一条赛事开始时间。",
              "sampleValue": "21:00"
            },
            "dtEnd": {
              "type": "string",
              "description": "下一条赛事结束时间。",
              "sampleValue": "22:40"
            },
            "eventLocation": {
              "type": "string",
              "description": "下一条赛事地点或场馆。",
              "sampleValue": "2号场"
            },
            "description": {
              "type": "string",
              "description": "下一条赛事状态或补充说明。",
              "sampleValue": "未开始"
            }
          }
        ]
      }
    },
    "ui": {
      "cardTitle": {
        "type": "string",
        "description": "卡片标题。",
        "sampleValue": "赛事日程"
      },
      "actionLabel": {
        "type": "string",
        "description": "顶部入口短标签。",
        "sampleValue": "详情"
      },
      "openLabel": {
        "type": "string",
        "description": "进入详情按钮文案。",
        "sampleValue": "看详情"
      },
      "possession": {
        "homeTeam": {
          "type": "string",
          "description": "比例条左侧队伍简称。",
          "sampleValue": "城东"
        },
        "awayTeam": {
          "type": "string",
          "description": "比例条右侧队伍简称。",
          "sampleValue": "海湾"
        },
        "homePercentText": {
          "type": "string",
          "description": "左侧比例展示文本。",
          "sampleValue": "58%"
        },
        "awayPercentText": {
          "type": "string",
          "description": "右侧比例展示文本。",
          "sampleValue": "42%"
        },
        "home": {
          "type": "number",
          "description": "左侧比例数值，用于 Progress.value。",
          "sampleValue": 58
        },
        "total": {
          "type": "number",
          "description": "比例总量，用于 Progress.total。",
          "sampleValue": 100
        }
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/calendar_fill.svg",
      "description": "日历实心图标，黑色，适合用于日程管理、赛事赛程与当日安排的识别入口。"
    }
  ]
}

